import { AxisScale } from '@visx/axis';
import { getTicks } from '@visx/scale';
import React from 'react';

import { DivAxisWrapper } from './DivAxisWrapper.js';
import { getTickValues } from '../../../functions/format-value.js';
import { getVerticalNumTicks } from '../../../functions/ticks.js';
import { TickValueFormatter } from '../../../types/tick-value.js';
import { AxisLeft } from '../AxisLeft.js';
import { axisFontProps } from '../constants.js';
import { getTickLabelPropsForValueAxis } from '../functions/get-tick-label-props.js';

/**
 * @internal
 */
export interface OldValueLeftAxisProps {
  scale: AxisScale;
  containerWidth: number;
  containerHeight: number;
  formatter?: TickValueFormatter;
  label?: string;
  stroke?: string;
}

const TICK_LABEL_PROPS = getTickLabelPropsForValueAxis('left');

/**
 * @internal
 */
export const OldValueLeftAxis = (props: OldValueLeftAxisProps) => {
  const { scale, containerHeight, containerWidth, label, formatter, stroke } =
    props;
  const numTicks = getVerticalNumTicks(containerHeight);
  const ticks = getTicks(scale, numTicks);
  const tickValues = getTickValues(ticks, formatter);
  const tickFormat = (_: unknown, index: number) => tickValues[index];

  return (
    <DivAxisWrapper
      divAxisStyle={axisFontProps}
      ticks={tickValues}
      label={label}
    >
      <AxisLeft
        data-testid="value-axis-left"
        scale={scale}
        containerSize={containerHeight}
        width={containerWidth}
        numTicks={numTicks}
        tickValues={ticks}
        tickLabelProps={TICK_LABEL_PROPS}
        tickFormat={tickFormat}
        label={label}
        stroke={stroke}
      />
    </DivAxisWrapper>
  );
};

OldValueLeftAxis['displayName'] = 'ValueLeftAxis';
